     1→// ============================================================
     2→// FVX 예제: fib_safety.fvx
     3→// Phase I — 재귀 정지 문제 및 자원 안전성 증명
     4→//
     5→// 증명 목표:
     6→//   1. fib(n) 계산의 재귀 깊이 ≤ n  (스택 오버플로 없음)
     7→//   2. DAG 전개: 순환 없이 의존성 그래프가 해소됨
     8→//   3. 자원 보존: fib(n) 계산에 필요한 노드 수 = 2n-1
     9→//
    10→// FVX 패러다임:
    11→//   - 재귀 = DAG evolve 체인 (순환 없음)
    12→//   - 스택 = 자원 소비 추적 (A2: 자원 보존 공리)
    13→//   - 정지 = DAG 말단 노드 수렴 (고정점)
    14→// ============================================================
    15→
    16→AXIOM {
    17→    // A1: 상태 존재
    18→    DEFINE n = 10;           // 입력값 (검증 대상)
    19→    DEFINE MAX_DEPTH = 10;   // 허용 최대 재귀 깊이
    20→
    21→    // A2: 자원 보존 — 재귀 호출 수
    22→    //     fib(n)의 전체 함수 호출 수 = 2*fib(n+1) - 1
    23→    DEFINE CALL_COUNT(n) -> 2 * fib(n+1) - 1;
    24→
    25→    // 피보나치 점화식
    26→    DEFINE fib(0) = 0;
    27→    DEFINE fib(1) = 1;
    28→    DEFINE fib(n) = fib(n-1) + fib(n-2)  WHERE n > 1;
    29→
    30→    // A3: 깊이 제약
    31→    ASSERT MAX_DEPTH >= n;
    32→    CONSTRAINT DEPTH_BOUND: recursion_depth <= MAX_DEPTH;
    33→
    34→    // A4: 시간 단조성 — 각 서브문제 크기 감소
    35→    //     fib(k)는 fib(k-1), fib(k-2)에 의존 (k 감소)
    36→    ASSERT SUBPROBLEM_DECREASES;
    37→}
    38→
    39→INVARIANT {
    40→    // 깊이 불변성: 재귀 스택 깊이는 n을 초과하지 않음
    41→    FORALL k: call_stack_depth(fib(k)) <= k;
    42→
    43→    // DAG 불변성: 의존성 그래프에 순환 없음
    44→    ACYCLIC dependency_graph;
    45→
    46→    // 자원 불변성: 생성된 IR 노드 수 ≤ 2n+1
    47→    node_count <= 2*n + 1;
    48→}
    49→
    50→MATCH IR {
    51→    // fib(n) → fib(n-1) + fib(n-2) 전개
    52→    BRIDGE "FreeJulia::Fibonacci_Recursive";
    53→
    54→    // 기저 케이스 (말단 노드)
    55→    NODE IR_STATE { state_id: 0, label: "fib_base_0" };
    56→    NODE IR_STATE { state_id: 1, label: "fib_base_1" };
    57→
    58→    // 재귀 전개 (각 단계 = EVOLVE)
    59→    UNFOLD n TIMES:
    60→        NODE   IR_EVOLVE { time_delta: 0, op: "fib_add" };
    61→        EDGE   EVOLVES from fib(k-1) to fib(k);
    62→        EDGE   EVOLVES from fib(k-2) to fib(k);
    63→
    64→    // 결과 관찰
    65→    OBSERVE IR_OBSERVE { label: "fib_result" };
    66→}
    67→
    68→SOLVE {
    69→    STRATEGY FixedPoint;
    70→    SCHEDULE TopDown;        // 큰 문제 → 작은 문제 (메모이제이션)
    71→    MAX_ITER 100;
    72→
    73→    // 수렴 조건: 모든 IR_STATE 노드 STABLE
    74→    CONVERGE_ON ALL_STATES_STABLE;
    75→
    76→    // 순환 감지: SCC 검사
    77→    DETECT_CYCLE {
    78→        ON_FOUND -> ABORT("순환 의존성 발견: 정지 불가");
    79→        EXPECTED NO_CYCLE;
    80→    }
    81→}
    82→
    83→PROOF {
    84→    // Termination (정지 증명):
    85→    //   measure μ(k) = k  (감소 수열)
    86→    //   fib(k) 계산은 fib(k-1), fib(k-2)에 의존 (μ 감소)
    87→    //   기저: fib(0) = 0, fib(1) = 1  (즉시 STABLE)
    88→    //   → 유한 스텝 내 모든 노드 STABLE  QED.
    89→    //
    90→    // Stack Safety (스택 안전성):
    91→    //   재귀 깊이 = 의존성 DAG의 최장 경로 = n
    92→    //   n ≤ MAX_DEPTH = 10  →  스택 오버플로 없음  QED.
    93→    //
    94→    // DAG 증명:
    95→    //   fib(k)는 fib(k-1), fib(k-2)에만 의존
    96→    //   k-1 < k, k-2 < k  →  역방향 엣지 없음
    97→    //   → 의존성 그래프 = DAG  QED.
    98→    //
    99→    // 자원 사용:
   100→    //   IR 노드 수 = 2 + (n-1)*2 + 1 = 2n+1
   101→    //   fib(10): 21개 노드, 깊이 10, 호출 177회
   102→
   103→    EXPECTED STABLE;
   104→    EXPECTED NO_CYCLE;
   105→    EXPECTED DEPTH_OK;
   106→    EXPECTED fib(10) = 55;
   107→}
