// ============================================================
// FVX 예제: conflict_test.fvx
// Phase Stress — 공리 충돌 탐지 (Axiom Conflict Detection)
//
// 증명 목표:
//   AXIOM A1 (x > 10) 과 AXIOM A2 (x < 5) 는 동시에 성립 불가
//   → 두 공리의 교집합이 공집합 (∅) 임을 증명
//   → Solver가 INCONSISTENT_AXIOMS 를 즉시 탐지해야 함
//
// FVX 패러다임:
//   - 충돌 감지 = 두 제약이 같은 IR_STATE에 연결되어 TOP 도달
//   - TOP 상태 = 격자의 최상단 (모순, 모든 것이 참 = 아무것도 증명 불가)
//   - 고정점이 TOP 이면 분석 결과는 무의미 → CONTRADICTION 선언
// ============================================================

AXIOM {
    // A1: 하한 제약 — x 는 10보다 커야 함
    ASSERT x > 10;

    // A2: 상한 제약 — x 는 5보다 작아야 함
    ASSERT x < 5;

    // A1 ∧ A2 = (x > 10) ∧ (x < 5)
    // 실수 영역에서 정수 영역 모두에서 이 교집합은 공집합:
    //   {x | x > 10} ∩ {x | x < 5} = ∅
    // → 두 공리를 동시에 만족하는 x는 존재하지 않음
}

INVARIANT {
    // 충돌 불변성: A1 ∧ A2 는 항상 거짓
    //   어떤 x 값도 두 조건을 동시에 만족할 수 없음
    FORALL x: NOT (x > 10 AND x < 5);

    // 도달 불가 구간 선언
    EMPTY_RANGE lower: 5, upper: 10;
    //   이 구간도 사실상 무의미 — [5, 10]은 A1도 A2도 만족 안 함
    //   진짜 충돌 구간: 두 조건의 합집합이 전체 실수지만
    //   교집합은 공집합이므로 "둘 다 만족"하는 점은 없음
}

MATCH IR {
    // 대상 상태: x = 7 (두 조건 모두 위반하는 구체적 증인)
    NODE IR_STATE { state_id: 7, label: "witness_x7" };

    // 충돌 경로 1: A1 위반 탐지
    //   GreaterThan(10) 검사 → x=7 은 7 ≤ 10 이므로 위반
    //   → 이 constraint는 TOP 으로 전이
    EDGE IR_CONSTRAINT { type: "GreaterThan", threshold: 10,
                         label: "axiom_A1",
                         on_violation: TOP };

    // 충돌 경로 2: A2 위반 탐지
    //   LessThan(5) 검사 → x=7 은 7 ≥ 5 이므로 위반
    //   → 이 constraint도 TOP 으로 전이
    EDGE IR_CONSTRAINT { type: "LessThan",    threshold: 5,
                         label: "axiom_A2",
                         on_violation: TOP };

    // 두 TOP 노드가 같은 IR_STATE 에 연결 → INCONSISTENT 판정
    OBSERVE IR_OBSERVE { label: "conflict_detector" };
}

SOLVE {
    STRATEGY ConflictDetect;
    SCHEDULE BreadthFirst;
    MAX_ITER 10;

    // 수렴 조건: TOP 노드 발견 즉시 중단
    CONVERGE_ON FIRST_TOP;

    // 충돌 탐지 활성화
    DETECT_CONTRADICTION {
        // TOP 에 도달한 노드가 있으면 INCONSISTENT_AXIOMS 선언
        ON_TOP    -> REPORT("INCONSISTENT_AXIOMS");

        // 두 constraint 모두 같은 상태에서 위반된 경우
        ON_MULTI_TOP -> REPORT("AXIOM_CONFLICT: A1 ∧ A2 = ∅");

        // 충돌 경로 기록: 어떤 공리가 위반인지 명시
        TRACE CONFLICT_PATH;
    }
}

PROOF {
    // 직접 증명 (x = 7 증인법):
    //   x = 7 을 대입하면:
    //     A1: 7 > 10  →  false  (위반)
    //     A2: 7 <  5  →  false  (위반)
    //   → x = 7 은 두 공리를 모두 위반함 → TOP 도달
    //
    // 완전성 증명:
    //   실수 전체 R 에서:
    //     {x ∈ R | x > 10} = (10, +∞)
    //     {x ∈ R | x <  5} = (-∞,  5)
    //     교집합 = (10, +∞) ∩ (-∞, 5) = ∅  (10 > 5 이므로)
    //   → 어떤 x 를 선택해도 두 공리를 동시에 만족 불가  QED.
    //
    // IR 관점:
    //   IR_STATE(7) → GreaterThan(10) → TOP
    //   IR_STATE(7) → LessThan(5)     → TOP
    //   두 경로 모두 TOP → 격자 최대원소 도달 → 분석 붕괴
    //   → Solver는 CONTRADICTION을 선언하고 즉시 종료해야 함

    EXPECTED CONTRADICTION;
    EXPECTED INCONSISTENT_AXIOMS;
}

// ============================================================
// FVX Deep Stress Test
// 실행: node tests/stress_test.js
//
// 세 가지 스트레스 테스트:
//   T1: 공리 충돌 탐지 (Axiom Conflict Detection)
//   T2: 대규모 의존성 전파 (Hyper-Scale N=1000+)
//   T3: 부동소수점 이진탐색 수렴 (√2, IEEE 754 precision)
// ============================================================

'use strict';

// ─────────────────────────────────────────────────────────────
// FVX Lattice 값 정의
// BOTTOM < 정상값 < TOP
// TOP    = 모순 (constraint 위반, 분석 붕괴)
// BOTTOM = 미초기화
// ─────────────────────────────────────────────────────────────
const LAT = Object.freeze({
    BOTTOM: 'BOTTOM',
    TOP:    'TOP',
    STABLE: 'STABLE',
});

// ─────────────────────────────────────────────────────────────
// IR 노드 타입
// ─────────────────────────────────────────────────────────────
const IR = Object.freeze({
    STATE:      'IR_STATE',
    EVOLVE:     'IR_EVOLVE',
    CONSTRAINT: 'IR_CONSTRAINT',
    OBSERVE:    'IR_OBSERVE',
});

// ─────────────────────────────────────────────────────────────
// IRGraph: FVX IR 그래프 구조
//
//   nodes  : Map<id, { type, data, value, lat }>
//   edges  : Map<id, id[]>  (from → [to, ...])
//   reverse: Map<id, id[]>  (to   → [from, ...])
// ─────────────────────────────────────────────────────────────
function createGraph() {
    return {
        nodes:   new Map(),
        edges:   new Map(),
        reverse: new Map(),
        _nextId: 0,
    };
}

function addNode(g, type, data) {
    const id = `n${g._nextId++}`;
    g.nodes.set(id, { id, type, data: Object.assign({}, data), lat: LAT.BOTTOM, value: null });
    g.edges.set(id, []);
    g.reverse.set(id, []);
    return id;
}

function addEdge(g, fromId, toId) {
    g.edges.get(fromId).push(toId);
    g.reverse.get(toId).push(fromId);
}

// ─────────────────────────────────────────────────────────────
// transfer 함수: 각 IR 노드 타입에 따른 값 전파
//
// IR_STATE      : 초기값을 그대로 보유
// IR_EVOLVE     : 의존 노드 값 + time_delta
// IR_CONSTRAINT : 조건 검사 → 위반 시 TOP, 통과 시 값 통과
//   - GreaterThan(t): value <= t  → TOP  (x > t 위반)
//   - LessThan(t)   : value >= t  → TOP  (x < t 위반)
//   - Bounded(l,u)  : value 가 [l,u] 밖 → TOP
//   - Convergence(ε): |hi-lo| < ε  → STABLE, else 계속
// ─────────────────────────────────────────────────────────────
function transfer(node, depValues) {
    const { type, data } = node;

    if (type === IR.STATE) {
        // 초기 IR_STATE: data.value 를 그대로 사용
        return { value: data.value, lat: LAT.STABLE };
    }

    if (type === IR.EVOLVE) {
        if (depValues.length === 0) return { value: null, lat: LAT.BOTTOM };
        // 단일 의존: 이전 값 + time_delta
        if (depValues.length === 1) {
            const prev = depValues[0];
            if (prev.lat === LAT.TOP) return { value: null, lat: LAT.TOP };
            if (prev.lat === LAT.BOTTOM) return { value: null, lat: LAT.BOTTOM };
            return { value: prev.value + (data.time_delta || 0), lat: LAT.STABLE };
        }
        // 다중 의존 (fib-style): 합산
        for (const d of depValues) {
            if (d.lat === LAT.TOP)    return { value: null, lat: LAT.TOP };
            if (d.lat === LAT.BOTTOM) return { value: null, lat: LAT.BOTTOM };
        }
        const sum = depValues.reduce((a, d) => a + d.value, 0);
        return { value: sum, lat: LAT.STABLE };
    }

    if (type === IR.CONSTRAINT) {
        if (depValues.length === 0) return { value: null, lat: LAT.BOTTOM };
        const dep = depValues[0];
        if (dep.lat === LAT.TOP)    return { value: null, lat: LAT.TOP };
        if (dep.lat === LAT.BOTTOM) return { value: null, lat: LAT.BOTTOM };

        const v = dep.value;
        const t = data.type;

        if (t === 'GreaterThan') {
            // x > threshold 공리 → value <= threshold 이면 위반
            if (v <= data.threshold) return { value: null, lat: LAT.TOP };
            return { value: v, lat: LAT.STABLE };
        }
        if (t === 'LessThan') {
            // x < threshold 공리 → value >= threshold 이면 위반
            if (v >= data.threshold) return { value: null, lat: LAT.TOP };
            return { value: v, lat: LAT.STABLE };
        }
        if (t === 'Bounded') {
            if (v < data.lower || v > data.upper) return { value: null, lat: LAT.TOP };
            return { value: v, lat: LAT.STABLE };
        }
        if (t === 'Convergence') {
            // 이진탐색 수렴용: data.lo, data.hi, data.epsilon
            const gap = Math.abs(data.hi - data.lo);
            if (gap < data.epsilon) return { value: v, lat: LAT.STABLE };
            return { value: v, lat: LAT.BOTTOM };
        }
        return { value: v, lat: LAT.STABLE };
    }

    if (type === IR.OBSERVE) {
        if (depValues.length === 0) return { value: null, lat: LAT.BOTTOM };
        const dep = depValues[0];
        return { value: dep.value, lat: dep.lat };
    }

    return { value: null, lat: LAT.BOTTOM };
}

// ─────────────────────────────────────────────────────────────
// solve: 워크리스트 기반 고정점 반복
//
//   반환: { iterations, topNodes, nodeResults, converged }
// ─────────────────────────────────────────────────────────────
function solve(g, maxIter) {
    maxIter = maxIter || 10000;

    // 모든 노드를 초기 워크리스트에 추가 (토폴로지 순 처리를 위해 전체 큐)
    let worklist = Array.from(g.nodes.keys());
    let iterations = 0;

    while (worklist.length > 0 && iterations < maxIter) {
        iterations++;
        const next = [];
        const changed = new Set();

        for (const nodeId of worklist) {
            const node = g.nodes.get(nodeId);
            const depIds = g.reverse.get(nodeId) || [];
            const depValues = depIds.map(id => {
                const n = g.nodes.get(id);
                return { value: n.value, lat: n.lat };
            });

            const result = transfer(node, depValues);

            if (result.lat !== node.lat || result.value !== node.value) {
                node.lat   = result.lat;
                node.value = result.value;
                changed.add(nodeId);
                // 변경된 노드의 후계자들을 다음 워크리스트에 추가
                for (const succ of (g.edges.get(nodeId) || [])) {
                    next.push(succ);
                }
            }
        }

        // 변경이 없으면 수렴
        if (changed.size === 0) break;
        worklist = next;
    }

    const topNodes = [];
    for (const [id, node] of g.nodes) {
        if (node.lat === LAT.TOP) topNodes.push({ id, data: node.data });
    }

    return { iterations, topNodes, nodeResults: g.nodes, converged: true };
}


